-- Provider-authorized Module 10; private resources, no entitlement or release changes.
begin;
insert into public.ce_course1_resources(id,data) values
('non_opioid_pain_pdf','{"base64": "", "sha256": "d84468fefdb7cdfe578b5720af1aaa9375e272cf707d23917bf080a11664f95e", "filename": "CE_HALO_Non_Opioid_Pain_Learner_FINAL.pdf", "mime_type": "application/pdf"}'::jsonb),
('non_opioid_pain_questions','[{"module_id": "course_1_module_10", "question_id": "course_1_module_10_q01", "question_number": 1, "stem": "Which of the following BEST captures the goal of multimodal analgesia in perioperative care?", "choice_a": "Combine agents with different mechanisms of action to improve pain control while reducing opioid-related adverse effects", "choice_b": "Substitute IV acetaminophen for oral acetaminophen in every patient", "choice_c": "Rely on a single high-dose non-opioid agent to avoid drug interactions", "choice_d": "Eliminate all opioid use in every surgical patient", "correct_choice": "a", "rationale": "Multimodal analgesia combines therapies that act at peripheral, spinal, and central levels of pain processing to improve control and reduce opioid requirements — not to eliminate opioids at all costs.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [1], "source_ids": [], "source_urls": ["https://pmc.ncbi.nlm.nih.gov/articles/PMC13439149/", "https://pubmed.ncbi.nlm.nih.gov/38499358/", "https://www.sciencedirect.com/science/article/pii/S0972978X24003222", "https://pmc.ncbi.nlm.nih.gov/articles/PMC7367437/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_10", "question_id": "course_1_module_10_q02", "question_number": 2, "stem": "Which opioid-related adverse effect is NOT typically reduced by an opioid-sparing multimodal regimen?", "choice_a": "PONV", "choice_b": "Malignant hyperthermia", "choice_c": "Ileus", "choice_d": "Respiratory depression", "correct_choice": "b", "rationale": "Malignant hyperthermia is a pharmacogenetic reaction to volatile anesthetics and succinylcholine — unrelated to opioid dose. Multimodal analgesia reduces PONV, ileus, sedation, and respiratory depression.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [1], "source_ids": [], "source_urls": ["https://pmc.ncbi.nlm.nih.gov/articles/PMC13439149/", "https://pubmed.ncbi.nlm.nih.gov/38499358/", "https://www.sciencedirect.com/science/article/pii/S0972978X24003222", "https://pmc.ncbi.nlm.nih.gov/articles/PMC7367437/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_10", "question_id": "course_1_module_10_q03", "question_number": 3, "stem": "Recent randomized controlled trial evidence in ambulatory spine surgery (Schwenk et al., 2024) suggests that IV acetaminophen, compared with oral acetaminophen:", "choice_a": "Produces substantially lower pain scores and opioid consumption", "choice_b": "Eliminates the need for NSAIDs postoperatively", "choice_c": "Shows little or no meaningful superiority when oral dosing can be given reliably", "choice_d": "Should always be substituted for oral acetaminophen in ERAS pathways", "correct_choice": "c", "rationale": "Recent RCT evidence shows minimal advantage of IV over oral acetaminophen when PO can be given reliably. IV is best reserved for NPO status, nausea, or unreliable GI absorption.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [3], "source_ids": [], "source_urls": ["https://pmc.ncbi.nlm.nih.gov/articles/PMC13439149/", "https://pubmed.ncbi.nlm.nih.gov/38499358/", "https://www.sciencedirect.com/science/article/pii/S0972978X24003222", "https://pmc.ncbi.nlm.nih.gov/articles/PMC7367437/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_10", "question_id": "course_1_module_10_q04", "question_number": 4, "stem": "The MOST appropriate role for IV acetaminophen in a cost-conscious perioperative practice is:", "choice_a": "Long-term outpatient analgesia after discharge", "choice_b": "Routine substitution for oral acetaminophen in every surgical patient", "choice_c": "First-line therapy for severe postoperative pain", "choice_d": "Selective use in patients who cannot take PO medication or when rapid early dosing is clinically important", "correct_choice": "d", "rationale": "IV acetaminophen remains substantially more expensive than oral, so selective use is the best-value approach — reserved for NPO patients, unreliable GI absorption, or when rapid dosing matters.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [3], "source_ids": [], "source_urls": ["https://pmc.ncbi.nlm.nih.gov/articles/PMC13439149/", "https://pubmed.ncbi.nlm.nih.gov/38499358/", "https://www.sciencedirect.com/science/article/pii/S0972978X24003222", "https://pmc.ncbi.nlm.nih.gov/articles/PMC7367437/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_10", "question_id": "course_1_module_10_q05", "question_number": 5, "stem": "For an adult weighing at least 50 kg without hepatic disease or other dose-limiting factors, which is the usual total daily acetaminophen range?", "choice_a": "3–4 g/day", "choice_b": "1–2 g/day", "choice_c": "8 g/day", "choice_d": "6 g/day", "correct_choice": "a", "rationale": "The usual maximum is up to 4 g/day from all products and routes; many pathways use lower limits. Weight below 50 kg, hepatic risk, and other patient factors require a different limit.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [3], "source_ids": [], "source_urls": ["https://pmc.ncbi.nlm.nih.gov/articles/PMC13439149/", "https://pubmed.ncbi.nlm.nih.gov/38499358/", "https://www.sciencedirect.com/science/article/pii/S0972978X24003222", "https://pmc.ncbi.nlm.nih.gov/articles/PMC7367437/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_10", "question_id": "course_1_module_10_q06", "question_number": 6, "stem": "Which of the following is a specific contraindication to ketorolac?", "choice_a": "Postpartum uterine cramping", "choice_b": "As prophylactic analgesia before major surgery and in the CABG setting", "choice_c": "Ambulatory knee arthroscopy in a healthy adult", "choice_d": "Postoperative outpatient orthopedic surgery in a young adult", "correct_choice": "b", "rationale": "Ketorolac is contraindicated as prophylactic analgesia before major surgery and in the setting of CABG surgery, per current labeling. It is also contraindicated in labor and delivery.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [3], "source_ids": [], "source_urls": ["https://pmc.ncbi.nlm.nih.gov/articles/PMC13439149/", "https://pubmed.ncbi.nlm.nih.gov/38499358/", "https://www.sciencedirect.com/science/article/pii/S0972978X24003222", "https://pmc.ncbi.nlm.nih.gov/articles/PMC7367437/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_10", "question_id": "course_1_module_10_q07", "question_number": 7, "stem": "What is the recommended MAXIMUM total duration of ketorolac use in adults?", "choice_a": "48 hours", "choice_b": "10 days", "choice_c": "5 days", "choice_d": "24 hours", "correct_choice": "c", "rationale": "Even when ketorolac is appropriate, use should be limited to a short course and not continued beyond 5 total days in adults, per prescribing information.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [3], "source_ids": [], "source_urls": ["https://pmc.ncbi.nlm.nih.gov/articles/PMC13439149/", "https://pubmed.ncbi.nlm.nih.gov/38499358/", "https://www.sciencedirect.com/science/article/pii/S0972978X24003222", "https://pmc.ncbi.nlm.nih.gov/articles/PMC7367437/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_10", "question_id": "course_1_module_10_q08", "question_number": 8, "stem": "Which patient is the BEST candidate for ketorolac?", "choice_a": "68-year-old with CKD stage 4 undergoing hip replacement", "choice_b": "45-year-old with active peptic ulcer disease post-cholecystectomy", "choice_c": "60-year-old on aspirin 325 mg daily with recent GI bleed", "choice_d": "32-year-old healthy adult post-laparoscopic appendectomy with good renal function and low bleeding risk", "correct_choice": "d", "rationale": "Advanced renal impairment, active PUD, recent GI bleeding, and concurrent aspirin/NSAID use are all contraindications or strong cautions. A healthy young adult post-laparoscopic surgery is the best candidate.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [3], "source_ids": [], "source_urls": ["https://pmc.ncbi.nlm.nih.gov/articles/PMC13439149/", "https://pubmed.ncbi.nlm.nih.gov/38499358/", "https://www.sciencedirect.com/science/article/pii/S0972978X24003222", "https://pmc.ncbi.nlm.nih.gov/articles/PMC7367437/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_10", "question_id": "course_1_module_10_q09", "question_number": 9, "stem": "In older adults or renal-risk patients when ketorolac is used at all, many clinicians favor which IV dose?", "choice_a": "15 mg IV", "choice_b": "30 mg IV", "choice_c": "60 mg IV", "choice_d": "5 mg IV", "correct_choice": "a", "rationale": "15 mg IV is commonly favored in older adults or renal-risk patients when ketorolac is used at all, given the higher AKI and bleeding risk profile.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [3], "source_ids": [], "source_urls": ["https://pmc.ncbi.nlm.nih.gov/articles/PMC13439149/", "https://pubmed.ncbi.nlm.nih.gov/38499358/", "https://www.sciencedirect.com/science/article/pii/S0972978X24003222", "https://pmc.ncbi.nlm.nih.gov/articles/PMC7367437/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_10", "question_id": "course_1_module_10_q10", "question_number": 10, "stem": "Which perioperative benefit is BEST supported for a single perioperative dose of dexamethasone in anterior cervical discectomy and fusion (ACDF)?", "choice_a": "Elimination of the need for regional anesthesia", "choice_b": "Reduced postoperative dysphagia and odynophagia", "choice_c": "Improved long-term fusion rate", "choice_d": "Prevention of malignant hyperthermia", "correct_choice": "b", "rationale": "In ACDF, the literature is particularly supportive of dexamethasone for reducing postoperative dysphagia and odynophagia by limiting soft-tissue inflammatory swelling. Current evidence suggests it does not clearly worsen long-term fusion outcomes.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [3], "source_ids": [], "source_urls": ["https://pmc.ncbi.nlm.nih.gov/articles/PMC13439149/", "https://pubmed.ncbi.nlm.nih.gov/38499358/", "https://www.sciencedirect.com/science/article/pii/S0972978X24003222", "https://pmc.ncbi.nlm.nih.gov/articles/PMC7367437/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_10", "question_id": "course_1_module_10_q11", "question_number": 11, "stem": "The single most important perioperative caution with dexamethasone in a diabetic patient is:", "choice_a": "Hypoglycemia", "choice_b": "Hyperkalemia", "choice_c": "Hyperglycemia", "choice_d": "Bradycardia", "correct_choice": "c", "rationale": "Perioperative hyperglycemia is the most common concern with dexamethasone, particularly in diabetic patients. Single-dose use is broadly accepted but requires glucose monitoring.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [3], "source_ids": [], "source_urls": ["https://pmc.ncbi.nlm.nih.gov/articles/PMC13439149/", "https://pubmed.ncbi.nlm.nih.gov/38499358/", "https://www.sciencedirect.com/science/article/pii/S0972978X24003222", "https://pmc.ncbi.nlm.nih.gov/articles/PMC7367437/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_10", "question_id": "course_1_module_10_q12", "question_number": 12, "stem": "The typical single perioperative IV dexamethasone dose used for antiemetic and analgesic adjunct effect is:", "choice_a": "100 mg", "choice_b": "0.5–1 mg", "choice_c": "20–40 mg", "choice_d": "4–10 mg", "correct_choice": "d", "rationale": "4–10 mg IV is the common single perioperative dose for antiemetic and analgesic adjunct effect in adult surgery.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [2], "source_ids": [], "source_urls": ["https://pmc.ncbi.nlm.nih.gov/articles/PMC13439149/", "https://pubmed.ncbi.nlm.nih.gov/38499358/", "https://www.sciencedirect.com/science/article/pii/S0972978X24003222", "https://pmc.ncbi.nlm.nih.gov/articles/PMC7367437/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_10", "question_id": "course_1_module_10_q13", "question_number": 13, "stem": "Low-dose ketamine''s opioid-sparing analgesic effect is primarily mediated by:", "choice_a": "NMDA receptor antagonism reducing central sensitization and wind-up", "choice_b": "Beta-2 adrenergic agonism", "choice_c": "Direct action at spinal mu-opioid receptors", "choice_d": "Inhibition of prostaglandin synthesis", "correct_choice": "a", "rationale": "Ketamine''s analgesic action is primarily NMDA receptor antagonism, reducing central sensitization and wind-up — a mechanism especially useful in major surgery and opioid-tolerant patients.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [2], "source_ids": [], "source_urls": ["https://pmc.ncbi.nlm.nih.gov/articles/PMC13439149/", "https://pubmed.ncbi.nlm.nih.gov/38499358/", "https://www.sciencedirect.com/science/article/pii/S0972978X24003222", "https://pmc.ncbi.nlm.nih.gov/articles/PMC7367437/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_10", "question_id": "course_1_module_10_q14", "question_number": 14, "stem": "Which patient population is MOST likely to benefit from a low-dose ketamine infusion as part of a multimodal plan?", "choice_a": "70-year-old undergoing cataract surgery under topical anesthesia", "choice_b": "Chronic-pain patient on high-dose baseline opioids undergoing major spine surgery", "choice_c": "Healthy 25-year-old undergoing outpatient wrist arthroscopy", "choice_d": "Healthy adult undergoing dental extraction", "correct_choice": "b", "rationale": "Ketamine is particularly useful in major surgery, opioid-tolerant patients, and procedures with high pain burden — chronic-pain patients on baseline opioids undergoing major spine surgery are a classic indication.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [2], "source_ids": [], "source_urls": ["https://pmc.ncbi.nlm.nih.gov/articles/PMC13439149/", "https://pubmed.ncbi.nlm.nih.gov/38499358/", "https://www.sciencedirect.com/science/article/pii/S0972978X24003222", "https://pmc.ncbi.nlm.nih.gov/articles/PMC7367437/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_10", "question_id": "course_1_module_10_q15", "question_number": 15, "stem": "The MAIN safety concern with perioperative IV lidocaine infusions is:", "choice_a": "Serotonin syndrome", "choice_b": "Adrenal suppression", "choice_c": "Local anesthetic systemic toxicity (LAST), particularly with concurrent regional anesthesia or hepatic dysfunction", "choice_d": "Malignant hyperthermia", "correct_choice": "c", "rationale": "Avoid concurrent or overlapping local-anesthetic effects. The consensus specifies at least 4-hour spacing around nerve blocks, and longer drug action may require more separation.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [3], "source_ids": [1], "source_urls": ["https://onlinelibrary.wiley.com/doi/10.1111/anae.15270"], "source_provenance": "verified_targeted_update"}, {"module_id": "course_1_module_10", "question_id": "course_1_module_10_q16", "question_number": 16, "stem": "Which IV lidocaine regimen matches the international perioperative consensus ceiling?", "choice_a": "Actual weight: 5 mg/kg rapid bolus", "choice_b": "Combine freely with a simultaneous local-anesthetic nerve block", "choice_c": "Continue 3 mg/kg/h indefinitely", "choice_d": "IBW-based: ≤1.5 mg/kg over 10 min, then ≤1.5 mg/kg/h for ≤24 h with reassessment", "correct_choice": "d", "rationale": "IV lidocaine is high risk. Use ideal body weight, avoid overlapping local-anesthetic action, and follow the protocol and monitoring requirements.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [2], "source_ids": [1], "source_urls": ["https://onlinelibrary.wiley.com/doi/10.1111/anae.15270"], "source_provenance": "verified_targeted_update"}, {"module_id": "course_1_module_10", "question_id": "course_1_module_10_q17", "question_number": 17, "stem": "The MAJOR practical limitation of intraoperative dexmedetomidine infusion is:", "choice_a": "Bradycardia and hypotension", "choice_b": "Tachycardia and hypertension", "choice_c": "Hyperkalemia", "choice_d": "Hyperthermia", "correct_choice": "a", "rationale": "Bradycardia and hypotension are the main practical limitations of dexmedetomidine. Many clinicians reduce or omit the loading dose to limit hemodynamic instability.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [2], "source_ids": [], "source_urls": ["https://pmc.ncbi.nlm.nih.gov/articles/PMC13439149/", "https://pubmed.ncbi.nlm.nih.gov/38499358/", "https://www.sciencedirect.com/science/article/pii/S0972978X24003222", "https://pmc.ncbi.nlm.nih.gov/articles/PMC7367437/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_10", "question_id": "course_1_module_10_q18", "question_number": 18, "stem": "Current 2024–2025 evidence suggests that perioperative gabapentinoids should be:", "choice_a": "Used routinely in every surgical patient", "choice_b": "Used selectively rather than routinely, with caution in older adults and OSA due to sedation and respiratory risk", "choice_c": "Combined with high-dose opioids for maximum effect", "choice_d": "Reserved only for outpatient cataract surgery", "correct_choice": "b", "rationale": "Current evidence has become more cautious. Gabapentinoids may reduce opioid use in selected settings but increase sedation, dizziness, and respiratory risk — particularly in older adults, OSA, and when combined with opioids or other sedatives.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [3], "source_ids": [], "source_urls": ["https://pmc.ncbi.nlm.nih.gov/articles/PMC13439149/", "https://pubmed.ncbi.nlm.nih.gov/38499358/", "https://www.sciencedirect.com/science/article/pii/S0972978X24003222", "https://pmc.ncbi.nlm.nih.gov/articles/PMC7367437/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_10", "question_id": "course_1_module_10_q19", "question_number": 19, "stem": "A patient with severe OSA is undergoing major abdominal surgery. Which agent warrants the MOST caution?", "choice_a": "Local wound infiltration with bupivacaine", "choice_b": "A single dose of dexamethasone 8 mg IV", "choice_c": "Oral pregabalin combined with opioids", "choice_d": "Acetaminophen", "correct_choice": "c", "rationale": "Pregabalin in this setting is oral, not IV. Combined sedative and respiratory effects are important in OSA and other high-risk patients.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [3], "source_ids": [2], "source_urls": ["https://pmc.ncbi.nlm.nih.gov/articles/PMC7367437/"], "source_provenance": "verified_targeted_update"}, {"module_id": "course_1_module_10", "question_id": "course_1_module_10_q20", "question_number": 20, "stem": "Magnesium''s adjunctive analgesic mechanism is primarily related to:", "choice_a": "Direct opioid receptor agonism", "choice_b": "Beta-blockade", "choice_c": "COX-1 and COX-2 inhibition", "choice_d": "NMDA-related mechanisms", "correct_choice": "d", "rationale": "Magnesium provides modest analgesic and opioid-sparing benefit through NMDA-related mechanisms. Its role is generally adjunctive rather than foundational.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [2], "source_ids": [], "source_urls": ["https://pmc.ncbi.nlm.nih.gov/articles/PMC13439149/", "https://pubmed.ncbi.nlm.nih.gov/38499358/", "https://www.sciencedirect.com/science/article/pii/S0972978X24003222", "https://pmc.ncbi.nlm.nih.gov/articles/PMC7367437/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_10", "question_id": "course_1_module_10_q21", "question_number": 21, "stem": "At higher exposure levels, a key perioperative concern with magnesium is:", "choice_a": "Potentiation of neuromuscular blockade and hypotension", "choice_b": "Serotonin syndrome", "choice_c": "Bronchoconstriction", "choice_d": "Malignant hyperthermia", "correct_choice": "a", "rationale": "At higher exposure levels, magnesium potentiates neuromuscular blockade and can cause hypotension and weakness — important considerations when used alongside NMBAs.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [2], "source_ids": [], "source_urls": ["https://pmc.ncbi.nlm.nih.gov/articles/PMC13439149/", "https://pubmed.ncbi.nlm.nih.gov/38499358/", "https://www.sciencedirect.com/science/article/pii/S0972978X24003222", "https://pmc.ncbi.nlm.nih.gov/articles/PMC7367437/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_10", "question_id": "course_1_module_10_q22", "question_number": 22, "stem": "Which non-opioid strategy is generally considered among the MOST powerful opioid-sparing interventions available to the CRNA?", "choice_a": "IV magnesium bolus without other adjuncts", "choice_b": "Regional and neuraxial techniques (peripheral nerve blocks, spinal, epidural)", "choice_c": "Preoperative high-dose oral acetaminophen alone", "choice_d": "Routine perioperative gabapentin", "correct_choice": "b", "rationale": "Regional and neuraxial techniques directly interrupt pain transmission and are often the single most powerful opioid-sparing intervention — they should be considered early, not as rescue.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [4], "source_ids": [], "source_urls": ["https://pmc.ncbi.nlm.nih.gov/articles/PMC13439149/", "https://pubmed.ncbi.nlm.nih.gov/38499358/", "https://www.sciencedirect.com/science/article/pii/S0972978X24003222", "https://pmc.ncbi.nlm.nih.gov/articles/PMC7367437/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_10", "question_id": "course_1_module_10_q23", "question_number": 23, "stem": "Which nonpharmacologic strategy is a valid — and essentially cost-free — component of multimodal perioperative pain management?", "choice_a": "Routine deep sedation for 48 hours postoperatively", "choice_b": "Withholding all analgesics to encourage patient tolerance", "choice_c": "Preoperative education, early mobilization, and ice/compression/elevation as appropriate", "choice_d": "Prolonged bed rest to avoid pain amplification", "correct_choice": "c", "rationale": "Preoperative education, early mobilization, and ice/compression/elevation are validated nonpharmacologic adjuncts that reduce pain amplification and improve function — with essentially no cost.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [5], "source_ids": [], "source_urls": ["https://pmc.ncbi.nlm.nih.gov/articles/PMC13439149/", "https://pubmed.ncbi.nlm.nih.gov/38499358/", "https://www.sciencedirect.com/science/article/pii/S0972978X24003222", "https://pmc.ncbi.nlm.nih.gov/articles/PMC7367437/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_10", "question_id": "course_1_module_10_q24", "question_number": 24, "stem": "A 78-year-old with early CKD (GFR 42) is scheduled for total knee replacement. Which multimodal plan is MOST appropriate?", "choice_a": "IV lidocaine infusion at 5 mg/kg/hr postoperatively without monitoring", "choice_b": "Opioid-only PCA for 48 hours", "choice_c": "Ketorolac 30 mg IV q6h × 5 days plus high-dose gabapentin 900 mg preop", "choice_d": "Regional block (adductor canal/IPACK), scheduled oral acetaminophen, careful consideration of NSAID risk, avoid routine gabapentinoids, single-dose dexamethasone", "correct_choice": "d", "rationale": "Regional techniques, scheduled acetaminophen, and single-dose dexamethasone are appropriate. NSAIDs (especially ketorolac at 30 mg) warrant caution in CKD, and routine gabapentinoids should be avoided in older adults given sedation and delirium risk.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [5], "source_ids": [], "source_urls": ["https://pmc.ncbi.nlm.nih.gov/articles/PMC13439149/", "https://pubmed.ncbi.nlm.nih.gov/38499358/", "https://www.sciencedirect.com/science/article/pii/S0972978X24003222", "https://pmc.ncbi.nlm.nih.gov/articles/PMC7367437/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_10", "question_id": "course_1_module_10_q25", "question_number": 25, "stem": "Which statement BEST summarizes the CRNA approach to non-opioid perioperative pain management?", "choice_a": "The safest strategy is the most appropriate combination for the procedure and the patient, not the largest regimen — with regional techniques and ERAS pathways guiding the plan", "choice_b": "Opioid PCA should always be first-line for postoperative pain", "choice_c": "IV acetaminophen and gabapentinoids should be given to every patient regardless of comorbidity", "choice_d": "Non-opioid means low-risk, so more agents are always better", "correct_choice": "a", "rationale": "Non-opioid does not automatically mean low-risk. Individualized, procedure-specific, patient-specific planning — with regional techniques and ERAS pathways as the backbone — is the current standard.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [5], "source_ids": [], "source_urls": ["https://pmc.ncbi.nlm.nih.gov/articles/PMC13439149/", "https://pubmed.ncbi.nlm.nih.gov/38499358/", "https://www.sciencedirect.com/science/article/pii/S0972978X24003222", "https://pmc.ncbi.nlm.nih.gov/articles/PMC7367437/"], "source_provenance": "provider_submitted_content_and_reference_list"}]'::jsonb)
